def U(names, minus=()):
    g = unary_union([P[n] for n in names])
    for m in minus:
        g = g.difference(P[m] if isinstance(m,str) else m)
    return g

UIGHUR_W = P['UIGHUR'].intersection(Polygon([[80,30],[91.5,30],[91.5,50],[80,50]]))
