for k,g in allg.items():
    parts = list(g.geoms) if g.geom_type=='MultiPolygon' else [g]
    main = orient(Polygon(max(parts,key=lambda p:p.area).exterior),1.0)
    simp = Polygon(res[k]['pts'])
    hd = main.hausdorff_distance(simp)
    res[k]['hausdorff_deg']=round(hd,2)
    feats.append({'type':'Feature','properties':{'key':k,'area_Mkm2_incl_inland_seas':res[k]['area_Mkm2'],'n_vertices':len(main.exterior.coords)},
                  'geometry':{'type':'Polygon','coordinates':[[[round(x,2),round(y,2)] for x,y in main.exterior.coords]]}})
